 db.orders.aggregate(
    [
       { 
          $group: 
             { 
                 _id: null, 
                 averageTime: 
                    { 
                       $avg:
                          { 
                             $dateDiff: 
                                { 
                                    startDate: "$purchased",
                                    endDate: "$delivered",
                                    unit: "day"
                                } 
                           }
                    }
             }
       },
       {
          $project:
             { 
                _id: 0,
                numDays: 
                   { 
                      $trunc: 
                         [ "$averageTime", 1 ]
                   }
             }
        }
    ]
)

